import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "../../generated/client-sqlite";
// Generated by scripts/prisma-generate.mjs from the same schema files, with only the provider changed.
import { PrismaClient as PostgresClient } from "../../generated/client-postgres";
import { isPostgres } from "./kind";

export const BUSY_TIMEOUT_MS = 10_000;

export const databasePath = () => (process.env.DATABASE_URL ?? "").replace(/^file:/, "");

const prismaClientSingleton = (): PrismaClient => {
  const url = process.env.DATABASE_URL ?? "";
  // Both clients come from one set of models, so the SQLite client's types describe either.
  if (isPostgres()) return new PostgresClient({ adapter: new PrismaPg({ connectionString: url }) }) as unknown as PrismaClient;
  return new PrismaClient({ adapter: new PrismaBetterSqlite3({ url, timeout: BUSY_TIMEOUT_MS }) });
};

declare const globalThis: {
  prismaGlobal: ReturnType<typeof prismaClientSingleton>;
} & typeof global;

const prisma = globalThis.prismaGlobal ?? prismaClientSingleton();

export default prisma;

if (process.env.NODE_ENV !== "production") globalThis.prismaGlobal = prisma;
